fun minMoves(n: Int, m: Int): Int {
    val total = n * m
    val moves = arrayOf(intArrayOf(0, 0), intArrayOf(-1, 0), intArrayOf(1, 0), intArrayOf(0, -1), intArrayOf(0, 1))
    var min = total
    for (mask in 0 until (1 shl total)) {
        val grid = Array(n) { IntArray(m) }
        var cnt = 0
        for (i in 0 until n) {
            for (j in 0 until m) {
                if (mask and (1 shl (i * m + j)) != 0) {
                    cnt++
                    grid[i][j] = 1
                }
            }
        }
        if (cnt >= min) continue
        val temp = Array(n) { IntArray(m) }
        for (i in 0 until n) {
            System.arraycopy(grid[i], 0, temp[i], 0, m)
        }
        var valid = true
        for (i in 0 until n) {
            for (j in 0 until m) {
                if (temp[i][j] == 1) {
                    var moved = false
                    for (k in 1..4) {
                        val ni = i + moves[k][0]
                        val nj = j + moves[k][1]
                        if (ni in 0 until n && nj in 0 until m && temp[ni][nj] == 0) {
                            temp[i][j] = 0
                            temp[ni][nj] = 1
                            moved = true
                            break
                        }
                    }
                    if (!moved) {
                        valid = false
                        break
                    }
                }
            }
            if (!valid) break
        }
        if (valid) {
            var occupied = 0
            for (i in 0 until n) {
                for (j in 0 until m) {
                    if (temp[i][j] == 1) occupied++
                }
            }
            if (occupied < min) min = occupied
        }
    }
    return min
}
