fun main() {
    val sc = Scanner(System.`in`)
    val n = sc.nextInt()
    val m = sc.nextInt()
    val total = n * m
    var maxFree = 0

    // Iterate over all possible subsets of cells to be empty (as bitmask)
    for (mask in 0 until (1 shl total)) {
        val empty = BitSet(total)
        for (i in 0 until total) {
            if ((mask and (1 shl i)) != 0) {
                empty.set(i)
            }
        }

        // Check if this subset is achievable
        val occupied = BitSet(total)
        var valid = true
        for (i in 0 until total) {
            if (empty[i]) continue
            val r = i / m
            val c = i % m
            var found = false
            // Try all 5 directions
            val dirs = arrayOf(intArrayOf(0, 0), intArrayOf(-1, 0), intArrayOf(1, 0), intArrayOf(0, -1), intArrayOf(0, 1))
            for (d in dirs) {
                val nr = r + d[0]
                val nc = c + d[1]
                if (nr in 0 until n && nc in 0 until m) {
                    val ni = nr * m + nc
                    if (!empty[ni]) {
                        occupied.set(ni)
                        found = true
                        break
                    }
                }
            }
            if (!found) {
                valid = false
                break
            }
        }
        if (valid) {
            // Check if all non-empty cells are covered by at least one spider
            var allCovered = true
            for (i in 0 until total) {
                if (!empty[i] && !occupied[i]) {
                    allCovered = false
                    break
                }
            }
            if (allCovered) {
                maxFree = maxOf(maxFree, empty.cardinality())
            }
        }
    }
    println(maxFree)
}
