    var maxFree = 0
    while (cells.isNotEmpty()) {
        val idx = cells.poll()
        val r = idx / m
        val c = idx % m
        val visited = Array(n) { BooleanArray(m) }
        val q = ArrayDeque<Int>()
        q.add(idx)
        visited[r][c] = true
        while (q.isNotEmpty()) {
            val cur = q.poll()
            val cr = cur / m
            val cc = cur % m
            for (d in dirs) {
                val nr = cr + d[0]
                val nc = cc + d[1]
                if (nr in 0 until n && nc in 0 until m && !visited[nr][nc]) {
                    visited[nr][nc] = true
                    q.add(nr * m + nc)
                }
            }
        }
        var count = 0
        for (i in 0 until n) for (j in 0 until m) if (!visited[i][j]) count++
        if (count > maxFree) maxFree = count
    }
    println(maxFree)
}
